#!/usr/bin/env node
/**
 * tests/adversarial-ui-m1-challenger2.js
 * 
 * Empirical Adversarial Test Harness for Milestone UI-M1
 * Challenger 2: Navigation Contracts, D-Pad Routing, View Switching & State Invariants
 * 
 * Target: CineJoy LG webOS UI Modernization (1080p, webOS 8.5)
 */

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved:', e1.message);
      process.exit(1);
    }
  }
}

// ANSI Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failures = [];

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Assertion failed');
  }
}

async function test(category, name, fn) {
  totalChecks++;
  const label = `[${category}] ${name}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
    console.error(`      ${C.red}Error: ${err.message}${C.reset}`);
    failures.push({ label, error: err.message });
  }
}

function makeRect(left, top, width, height) {
  return {
    left: left,
    top: top,
    right: left + width,
    bottom: top + height,
    width: width,
    height: height,
    x: left,
    y: top
  };
}

/**
 * Creates an integrated DOM environment with HTML, CSS, SpatialNav, and CinejoyApp loaded
 */
function createIntegratedAppDom(initialRoute = 'home') {
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const navPath = path.resolve(__dirname, '../app/js/navigation.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + initialRoute,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  // Polyfills for layout and scroll
  window.Element.prototype.scrollIntoView = function () {};
  window.Element.prototype.scrollTo = function () {};

  // Mock getBoundingClientRect with accurate 1920x1080 TV geometry
  window.Element.prototype.getBoundingClientRect = function () {
    const view = this.closest('.view');
    if (view && !view.classList.contains('active')) {
      return makeRect(0, 0, 0, 0);
    }
    if (this.style.display === 'none' || this.style.visibility === 'hidden') {
      return makeRect(0, 0, 0, 0);
    }

    const id = this.id;
    if (id === 'header-brand' || this.classList.contains('brand-container')) {
      return makeRect(96, 20, 200, 48);
    }
    if (this.classList.contains('nav-pill-item')) {
      const route = this.getAttribute('data-route');
      if (route === 'home') return makeRect(780, 24, 80, 40);
      if (route === 'movies') return makeRect(866, 24, 90, 40);
      if (route === 'series') return makeRect(962, 24, 86, 40);
      if (route === 'search') return makeRect(1054, 24, 94, 40);
      return makeRect(780, 24, 80, 40);
    }

    if (id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
    if (id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
    if (id === 'hero-list-btn') return makeRect(433, 460, 140, 56);
    if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (id === 'details-trailer-btn') return makeRect(292, 450, 160, 56);
    if (id === 'player-back-btn') return makeRect(96, 54, 56, 56);
    if (id === 'osd-play-btn') return makeRect(912, 940, 96, 96);

    // Shelf cards mock
    if (this.classList.contains('card-poster')) {
      return makeRect(96, 600, 220, 330);
    }

    return makeRect(0, 0, 100, 50);
  };

  const configCode = fs.readFileSync(configPath, 'utf8');
  const navCode = fs.readFileSync(navPath, 'utf8');
  const appCode = fs.readFileSync(appPath, 'utf8');

  window.eval(configCode);
  window.eval(navCode);
  window.eval(appCode);

  return { dom, window, spatialNav: window.SpatialNav, app: window.CinejoyApp };
}

async function runAllChallengerTests() {
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}► CHALLENGER 2: MILESTONE UI-M1 EMPIRICAL ADVERSARIAL VERIFICATION${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

  // ===========================================================================
  // SUITE 1: Navigation Contracts & Attribute Invariants
  // ===========================================================================
  console.log(`${C.bold}${C.magenta}▶ SUITE 1: Navigation Contracts & Header Attributes Invariants${C.reset}`);

  await test('CONTRACT', 'Header element exists with id="app-header", class="app-header", and role="banner"', async () => {
    const { window } = createIntegratedAppDom();
    const header = window.document.getElementById('app-header');
    assert(header, 'Missing #app-header');
    assert(header.classList.contains('app-header'), 'Header must contain .app-header class');
    assert(header.getAttribute('role') === 'banner', 'Header must have role="banner"');
  });

  await test('CONTRACT', 'Brand anchor has data-nav="true", data-nav-group="header", data-route="home"', async () => {
    const { window } = createIntegratedAppDom();
    const brand = window.document.getElementById('header-brand');
    assert(brand, 'Missing #header-brand element');
    assert(brand.getAttribute('data-nav') === 'true', 'Brand must have data-nav="true"');
    assert(brand.getAttribute('data-nav-group') === 'header', 'Brand must have data-nav-group="header"');
    assert(brand.getAttribute('data-route') === 'home', 'Brand must have data-route="home"');
    assert(brand.getAttribute('href') === '#home', 'Brand must link to #home');
  });

  await test('CONTRACT', 'Nav container has id="header-nav", classes .nav-glass-pill and .pill, role="navigation"', async () => {
    const { window } = createIntegratedAppDom();
    const nav = window.document.getElementById('header-nav');
    assert(nav, 'Missing #header-nav element');
    assert(nav.classList.contains('nav-glass-pill'), 'Nav container missing .nav-glass-pill');
    assert(nav.classList.contains('pill'), 'Nav container missing .pill');
    assert(nav.getAttribute('role') === 'navigation', 'Nav container missing role="navigation"');
  });

  await test('CONTRACT', 'All 4 pill items retain data-nav="true", data-nav-group="header", and valid data-route', async () => {
    const { window } = createIntegratedAppDom();
    const expected = [
      { id: 'header-nav-home', route: 'home', href: '#home', label: 'Home' },
      { id: 'header-nav-movies', route: 'movies', href: '#movies', label: 'Movies' },
      { id: 'header-nav-series', route: 'series', href: '#series', label: 'Series' },
      { id: 'header-nav-search', route: 'search', href: '#search', label: 'Search' }
    ];

    for (const exp of expected) {
      const el = window.document.getElementById(exp.id);
      assert(el, `Missing #${exp.id}`);
      assert(el.getAttribute('data-nav') === 'true', `${exp.id} missing data-nav="true"`);
      assert(el.getAttribute('data-nav-group') === 'header', `${exp.id} missing data-nav-group="header"`);
      assert(el.getAttribute('data-route') === exp.route, `${exp.id} data-route mismatch: got ${el.getAttribute('data-route')}`);
      assert(el.getAttribute('href') === exp.href, `${exp.id} href mismatch: got ${el.getAttribute('href')}`);
      assert(el.classList.contains('nav-pill-item'), `${exp.id} missing class .nav-pill-item`);
      assert(el.classList.contains('tab'), `${exp.id} missing class .tab`);
      const span = el.querySelector('span');
      assert(span && span.textContent.trim() === exp.label, `${exp.id} text label mismatch`);
    }
  });

  await test('CONTRACT', 'Nav divider exists between series and search tabs', async () => {
    const { window } = createIntegratedAppDom();
    const divider = window.document.querySelector('#header-nav .nav-divider');
    assert(divider, 'Missing .nav-divider in #header-nav');
    const seriesEl = window.document.getElementById('header-nav-series');
    const searchEl = window.document.getElementById('header-nav-search');
    assert(seriesEl.nextElementSibling === divider, '.nav-divider should immediately follow #header-nav-series');
    assert(divider.nextElementSibling === searchEl, '#header-nav-search should immediately follow .nav-divider');
  });

  // ===========================================================================
  // SUITE 2: View Switching, Active Pill Indicators & Player Header Hiding
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 2: View Switching & Active Pill State Invariants${C.reset}`);

  await test('VIEW_SWITCH', 'Initial boot on home view activates only #header-nav-home pill', async () => {
    const { window, app } = createIntegratedAppDom('home');
    app.init();

    const homePill = window.document.getElementById('header-nav-home');
    const moviesPill = window.document.getElementById('header-nav-movies');
    const seriesPill = window.document.getElementById('header-nav-series');
    const searchPill = window.document.getElementById('header-nav-search');

    assert(homePill.classList.contains('active'), 'Home pill must have .active on initial boot');
    assert(!moviesPill.classList.contains('active'), 'Movies pill must NOT have .active');
    assert(!seriesPill.classList.contains('active'), 'Series pill must NOT have .active');
    assert(!searchPill.classList.contains('active'), 'Search pill must NOT have .active');

    const header = window.document.getElementById('app-header');
    assert(!header.classList.contains('header-hidden'), 'Header must NOT be hidden on home');
  });

  await test('VIEW_SWITCH', 'switchView("movies") updates active pill to movies and clears other pills', async () => {
    const { window, app } = createIntegratedAppDom('home');
    app.init();
    app.switchView('movies');

    assert(app.state.currentView === 'movies', 'state.currentView must be movies');
    const homePill = window.document.getElementById('header-nav-home');
    const moviesPill = window.document.getElementById('header-nav-movies');
    assert(!homePill.classList.contains('active'), 'Home pill must lose .active');
    assert(moviesPill.classList.contains('active'), 'Movies pill must gain .active');

    const viewMovies = window.document.getElementById('view-movies');
    assert(viewMovies.classList.contains('active'), '#view-movies must have .active');
    const viewHome = window.document.getElementById('view-home');
    assert(!viewHome.classList.contains('active'), '#view-home must lose .active');
  });

  await test('VIEW_SWITCH', 'switchView("series") updates active pill to series', async () => {
    const { window, app } = createIntegratedAppDom('movies');
    app.init();
    app.switchView('series');

    assert(app.state.currentView === 'series', 'state.currentView must be series');
    const seriesPill = window.document.getElementById('header-nav-series');
    assert(seriesPill.classList.contains('active'), 'Series pill must gain .active');
    const moviesPill = window.document.getElementById('header-nav-movies');
    assert(!moviesPill.classList.contains('active'), 'Movies pill must lose .active');
  });

  await test('VIEW_SWITCH', 'switchView("search") updates active pill to search', async () => {
    const { window, app } = createIntegratedAppDom('series');
    app.init();
    app.switchView('search');

    assert(app.state.currentView === 'search', 'state.currentView must be search');
    const searchPill = window.document.getElementById('header-nav-search');
    assert(searchPill.classList.contains('active'), 'Search pill must gain .active');
    const seriesPill = window.document.getElementById('header-nav-series');
    assert(!seriesPill.classList.contains('active'), 'Series pill must lose .active');
  });

  await test('VIEW_SWITCH', 'switchView("player") HIDES header (.header-hidden) and removes pill active states', async () => {
    const { window, app } = createIntegratedAppDom('home');
    app.init();
    app.switchView('player');

    assert(app.state.currentView === 'player', 'state.currentView must be player');
    const header = window.document.getElementById('app-header');
    assert(header.classList.contains('header-hidden'), 'Header MUST have .header-hidden class on player view');

    const pills = window.document.querySelectorAll('.nav-pill-item');
    pills.forEach(p => {
      assert(!p.classList.contains('active'), `Pill #${p.id} must NOT have .active when in player view`);
    });
  });

  await test('VIEW_SWITCH', 'exitPlayer restores header visibility and previous view active pill', async () => {
    const { window, app } = createIntegratedAppDom('movies');
    app.init();
    app.switchView('movies');
    app.switchView('player');

    const header = window.document.getElementById('app-header');
    assert(header.classList.contains('header-hidden'), 'Header must be hidden on player view');

    app.exitPlayer();

    assert(app.state.currentView === 'movies', 'Must return to previous view (movies)');
    assert(!header.classList.contains('header-hidden'), 'Header MUST unhide (.header-hidden removed) on exiting player');
    const moviesPill = window.document.getElementById('header-nav-movies');
    assert(moviesPill.classList.contains('active'), 'Movies pill must regain .active');
  });

  await test('VIEW_SWITCH', 'Rapid 100-switch randomized stress test maintains single-active invariant', async () => {
    const { window, app } = createIntegratedAppDom('home');
    app.init();

    const targets = ['home', 'movies', 'series', 'search', 'details', 'player'];
    for (let i = 0; i < 100; i++) {
      const next = targets[i % targets.length];
      app.switchView(next);

      // Invariant 1: Exactly one view is active
      const activeViews = window.document.querySelectorAll('.view.active');
      assert(activeViews.length === 1, `Iteration ${i}: Expected exactly 1 active view, found ${activeViews.length}`);
      assert(activeViews[0].id === `view-${next}`, `Iteration ${i}: Active view id should be #view-${next}`);

      // Invariant 2: Header hidden strictly when next === 'player'
      const header = window.document.getElementById('app-header');
      if (next === 'player') {
        assert(header.classList.contains('header-hidden'), `Iteration ${i}: Header must have .header-hidden on player`);
      } else {
        assert(!header.classList.contains('header-hidden'), `Iteration ${i}: Header must NOT have .header-hidden on ${next}`);
      }

      // Invariant 3: At most one pill is active, and if active, its data-route matches next
      const activePills = window.document.querySelectorAll('.nav-pill-item.active');
      if (['home', 'movies', 'series', 'search'].includes(next)) {
        assert(activePills.length === 1, `Iteration ${i}: Expected 1 active pill for route ${next}, found ${activePills.length}`);
        assert(activePills[0].getAttribute('data-route') === next, `Active pill data-route mismatch on ${next}`);
      } else {
        assert(activePills.length === 0, `Iteration ${i}: Expected 0 active pills for route ${next}, found ${activePills.length}`);
      }
    }
  });

  // ===========================================================================
  // SUITE 3: Spatial Remote & D-pad Routing between Header and View
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 3: Spatial D-Pad Navigation & Focus Cycling${C.reset}`);

  await test('DPAD', 'SpatialNav.getCandidates() includes header items when header is visible', async () => {
    const { spatialNav, app } = createIntegratedAppDom('home');
    app.init();

    const candidates = spatialNav.getCandidates();
    const candidateIds = candidates.map(el => el.id);

    assert(candidateIds.includes('header-brand'), 'Candidates must include #header-brand');
    assert(candidateIds.includes('header-nav-home'), 'Candidates must include #header-nav-home');
    assert(candidateIds.includes('header-nav-movies'), 'Candidates must include #header-nav-movies');
    assert(candidateIds.includes('header-nav-series'), 'Candidates must include #header-nav-series');
    assert(candidateIds.includes('header-nav-search'), 'Candidates must include #header-nav-search');
  });

  await test('DPAD', 'SpatialNav.getCandidates() EXCLUDES all header items when view="player" (header-hidden)', async () => {
    const { window, spatialNav, app } = createIntegratedAppDom('home');
    app.init();
    app.switchView('player');

    const header = window.document.getElementById('app-header');
    assert(header.classList.contains('header-hidden'), 'Header must have .header-hidden');

    const candidates = spatialNav.getCandidates();
    for (const c of candidates) {
      assert(c.getAttribute('data-nav-group') !== 'header', `Candidate #${c.id} belongs to header group but header is hidden!`);
    }
  });

  await test('DPAD', 'D-pad horizontal focus traversal across Header Navigation Pill', async () => {
    const { window, spatialNav, app } = createIntegratedAppDom('home');
    app.init();

    const homePill = window.document.getElementById('header-nav-home');
    spatialNav.setFocus(homePill);
    assert(spatialNav.getFocus() === homePill, 'Focus should start at #header-nav-home');

    // ArrowRight -> Movies
    spatialNav.move('right');
    const moviesPill = window.document.getElementById('header-nav-movies');
    assert(spatialNav.getFocus() === moviesPill, `Expected focus on #header-nav-movies, got #${spatialNav.getFocus()?.id}`);

    // ArrowRight -> Series
    spatialNav.move('right');
    const seriesPill = window.document.getElementById('header-nav-series');
    assert(spatialNav.getFocus() === seriesPill, `Expected focus on #header-nav-series, got #${spatialNav.getFocus()?.id}`);

    // ArrowRight -> Search
    spatialNav.move('right');
    const searchPill = window.document.getElementById('header-nav-search');
    assert(spatialNav.getFocus() === searchPill, `Expected focus on #header-nav-search, got #${spatialNav.getFocus()?.id}`);

    // ArrowLeft -> Back to Series
    spatialNav.move('left');
    assert(spatialNav.getFocus() === seriesPill, `Expected focus on #header-nav-series, got #${spatialNav.getFocus()?.id}`);

    // ArrowLeft -> Back to Movies
    spatialNav.move('left');
    assert(spatialNav.getFocus() === moviesPill, `Expected focus on #header-nav-movies, got #${spatialNav.getFocus()?.id}`);

    // ArrowLeft -> Back to Home
    spatialNav.move('left');
    assert(spatialNav.getFocus() === homePill, `Expected focus on #header-nav-home, got #${spatialNav.getFocus()?.id}`);

    // ArrowLeft -> Brand
    spatialNav.move('left');
    const brand = window.document.getElementById('header-brand');
    assert(spatialNav.getFocus() === brand, `Expected focus on #header-brand, got #${spatialNav.getFocus()?.id}`);
  });

  await test('DPAD', 'D-pad vertical transition from Header DOWN into View Container elements', async () => {
    const { window, spatialNav, app } = createIntegratedAppDom('home');
    app.init();

    const homePill = window.document.getElementById('header-nav-home');
    spatialNav.setFocus(homePill);

    // ArrowDown should move from header (y=24) to Hero Play Button (y=460)
    spatialNav.move('down');
    const focused = spatialNav.getFocus();
    assert(focused, 'Focus must move into view on ArrowDown');
    assert(focused.id === 'hero-play-btn', `Expected focus to land on #hero-play-btn, got #${focused.id}`);
  });

  await test('DPAD', 'D-pad vertical transition from View Container UP into Header Pill bar', async () => {
    const { window, spatialNav, app } = createIntegratedAppDom('home');
    app.init();

    const heroPlay = window.document.getElementById('hero-play-btn');
    spatialNav.setFocus(heroPlay);

    // ArrowUp should move from Hero Play (y=460) up to Header
    spatialNav.move('up');
    const focused = spatialNav.getFocus();
    assert(focused, 'Focus must return to header on ArrowUp');
    assert(focused.getAttribute('data-nav-group') === 'header', `Expected focus in header group, got #${focused.id}`);
  });

  await test('DPAD', 'Selecting / clicking a nav pill triggers switchView and updates active classes', async () => {
    const { window, app } = createIntegratedAppDom('home');
    app.init();

    const moviesPill = window.document.getElementById('header-nav-movies');
    // Simulate user click on movies pill
    moviesPill.click();

    assert(app.state.currentView === 'movies', 'Clicking #header-nav-movies must switchView to movies');
    assert(moviesPill.classList.contains('active'), 'Movies pill must have .active class');
    const homePill = window.document.getElementById('header-nav-home');
    assert(!homePill.classList.contains('active'), 'Home pill must lose .active class');
  });

  // ===========================================================================
  // SUITE 4: State Preservation & Service Invariants
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 4: State Preservation & Service Invariants${C.reset}`);

  await test('INVARIANT', 'services/com.cinejoy.tv.service/ files remain 100% byte-for-byte immutable', async () => {
    const svcDir = path.resolve(__dirname, '../services/com.cinejoy.tv.service');
    const expectedFiles = [
      'index.js',
      'resolver.js',
      'hls-proxy.js',
      'http-client.js',
      'crush.wasm',
      'services.json',
      'package.json'
    ];

    for (const f of expectedFiles) {
      const p = path.join(svcDir, f);
      assert(fs.existsSync(p), `Missing required service file: ${f}`);
    }

    // Verify crush.wasm exact size
    const wasmStat = fs.statSync(path.join(svcDir, 'crush.wasm'));
    assert(wasmStat.size === 67222, `crush.wasm size must be exactly 67,222 bytes, got ${wasmStat.size}`);
  });

  await test('INVARIANT', 'app/js/config.js maintains default proxyBaseUrl at 127.0.0.1:8088', async () => {
    const { window } = createIntegratedAppDom();
    assert(window.CINEJOY_CONFIG, 'CINEJOY_CONFIG must be defined');
    assert(window.CINEJOY_CONFIG.proxyBaseUrl === 'http://127.0.0.1:8088', `Expected default proxyBaseUrl to be 127.0.0.1:8088, got ${window.CINEJOY_CONFIG.proxyBaseUrl}`);
  });

  await test('INVARIANT', 'Luna keepalive hook in app.js registers subscription on launch', async () => {
    const appCode = fs.readFileSync(path.resolve(__dirname, '../app/js/app.js'), 'utf8');
    assert(appCode.includes('luna://com.cinejoy.tv.service'), 'app.js must target luna://com.cinejoy.tv.service');
    assert(appCode.includes("'keepalive'"), 'app.js must request keepalive method');
    assert(appCode.includes('subscribe: true'), 'app.js must specify subscribe: true');
  });

  // ===========================================================================
  // SUMMARY & VERDICT
  // ===========================================================================
  console.log(`\n${C.bold}========================================================================${C.reset}`);
  console.log(`${C.bold}► CHALLENGER 2 SUMMARY REPORT${C.reset}`);
  console.log(`------------------------------------------------------------------------`);
  console.log(`  Total Checks Executed:  ${totalChecks}`);
  console.log(`  Passed Checks:          ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:          ${failedChecks === 0 ? C.green + '0' : C.red + failedChecks}${C.reset}`);
  console.log(`------------------------------------------------------------------------`);

  if (failedChecks === 0) {
    console.log(`${C.green}${C.bold}VERDICT: APPROVE (100% of Empirical Navigation & State Checks Passed)${C.reset}\n`);
    process.exit(0);
  } else {
    console.log(`${C.red}${C.bold}VERDICT: REJECT (${failedChecks} Failure(s) Detected)${C.reset}\n`);
    failures.forEach((f, idx) => {
      console.log(`  [${idx + 1}] ${f.label}: ${f.error}`);
    });
    process.exit(1);
  }
}

runAllChallengerTests().catch(err => {
  console.error('Unhandled harness exception:', err);
  process.exit(1);
});

